<template>
	<view class="container">
		<!-- 顶部导航栏 -->
		<view class="nav-header">
			<text class="title">{{ isFromHome ? '我周围的圈子' : '我的圈子' }}</text>
		</view>

		<!-- 列表区域 -->
		<scroll-view class="scroll-view" scroll-y @scrolltolower="loadMore">
			<!-- 列表内容 -->
			<view class="list">
				<view class="item" v-for="item in circleStore.list" :key="item.circleId">
					<view class="item-content">
						<image class="avatar" :src="getAvatar(item)" mode="aspectFill" />
						<view class="info">
							<text class="owner">{{getOwnerName(item)}}发起</text>
							<text class="name">{{item.circleName}}</text>
							<view class="meta">
								<text class="time">{{item.createTime}}</text>
								<text class="distance">{{item.distance}}公里</text>
							</view>
						</view>
						<button class="view-btn" @click.stop="navigateToDetail(item)">
							<text class="btn-text">查看</text>
						</button>
					</view>
				</view>
			</view>

			<!-- 加载提示 -->
			<view class="loading" v-if="circleStore.loading">加载中...</view>
			<view class="no-more" v-if="!circleStore.loading && !circleStore.pagination.hasMore">
				没有更多了
			</view>
		</scroll-view>

		<!-- 底部按钮 -->
		<view class="footer">
			<button class="create-btn" @click="createCircle">
				<text class="btn-text">创建你的圈子</text>
			</button>
		</view>
	</view>
</template>

<script>
	import {
		useCircleStore
	} from '@/store/circle'
	import {
		useUserStore
	} from '@/store/user'
	import {
		userApi,
		circleApi
	} from '@/request/api'

	export default {
		setup() {
			const circleStore = useCircleStore()
			const userStore = useUserStore()
			return {
				circleStore,
				userStore
			}
		},

		data() {
			return {
				list: [],
				pagination: {
					current: 1,
					size: 10,
					total: 0
				},
				loading: false,
				refreshing: false,
				isFromHome: true
			}
		},

		async onLoad(options) {
			await this.loadCurrentPage(options)
		},
		async onShow(){
			await this.loadCurrentPage(options)
		},

		async onTabItemTap(item) {
			if (item.index === 0) {
				this.isFromHome = true
				uni.setNavigationBarTitle({
					title: '圈子'
				})
				await this.loadCurrentPage({})
			}
		},

		methods: {
			async loadCurrentPage(options){
				const userId = await uni.getStorageSync('token')
				this.isFromHome = !options.type || options.type !== 'my'
				uni.setNavigationBarTitle({
					title: this.isFromHome ? '圈子' : '我的圈子'
				})
				
				// #ifdef MP-WEIXIN
				if (uni.getSystemInfoSync().platform === 'devtools') {
					console.log('模拟器环境，使用默认位置信息')
					let param = {
						isRefresh: true,
						longitude: 116.24145697699653,
						latitude: 39.93208468967014
					}
					if (!this.isFromHome && userId) {
						param['userId'] = userId
					}
					this.circleStore.getCircleList(param)
					return
				}
				// #endif
				
				uni.getLocation({
					type: 'gcj02',
					success: ({
						longitude,
						latitude
					}) => {
						let param = {
							isRefresh: true,
							longitude,
							latitude
						}
						if (!this.isFromHome && userId) {
							param['userId'] = userId
						}
						this.circleStore.getCircleList(param)
					},
					fail: (err) => {
						// let param = {
						// 	isRefresh: true
						// }
						// if (!this.isFromHome && userId) {
						// 	param['userId'] = userId
						// }
						// console.error('获取位置失败：', err)
						// this.circleStore.getCircleList(param)
						uni.showToast({
							title: err.message || '获取位置失败',
							icon: 'none'
						})
					}
				})
			},
			
			loadMore() {
				// console.log('触发加载更多')
				// if (!this.circleStore.loading && this.circleStore.pagination.hasMore) {
				// 	this.circleStore.getCircleList({
				// 		isRefresh: true
				// 	})
				// }
			},

			getAvatar(item) {
				return item.ownerImage ? item.ownerImage : "/static/default-avatar.png";
			},

			getOwnerName(item) {
				return item.ownerName ? item.ownerName : "某某"
			},

			async createCircle() {
				await this.userStore.checkLoginStatus()
				uni.navigateTo({
					url: '/pages/circle/create'
				})
			},

			navigateToDetail(item) {
				uni.navigateTo({
					url: `/pages/circle/detail?circleId=${item.circleId}`
				})
			}
		}
	}
</script>

<style lang="scss" scoped>
	.container {
		height: 100vh;
		display: flex;
		flex-direction: column;
		background: #fff;
	}

	.nav-header {
		padding: 44px 16px 12px;
		background: #000;
		position: relative;

		.title {
			color: #fff;
			font-size: 18px;
			text-align: center;
			display: block;
		}

		.user-icon {
			position: absolute;
			right: 16px;
			top: 44px;
		}
	}

	.scroll-view {
		flex: 1;
		height: 0;
	}

	.list {
		padding: 0 16px;

		.item {
			padding: 16px 0;
			border-bottom: 1px solid #f5f5f5;

			.item-content {
				display: flex;
				align-items: center;
			}

			.avatar {
				width: 40px;
				height: 40px;
				border-radius: 20px;
				margin-right: 12px;
				background: #f5f5f5;
			}

			.info {
				flex: 1;
				margin-right: 12px;

				.name {
					font-size: 16px;
					color: #333;
					font-weight: 500;
					margin-bottom: 4px;
					display: block;
				}

				.owner {
					font-size: 14px;
					color: #666;
					margin-bottom: 4px;
					display: block;
				}

				.meta {
					font-size: 12px;
					color: #999;
					display: flex;
					align-items: center;

					.time {
						margin-right: 12px;
					}
				}
			}

			.view-btn {
				min-width: 64px;
				height: 32px;
				line-height: 30px;
				font-size: 14px;
				color: #4080ff;
				background: rgba(64, 128, 255, 0.1);
				border: 1px solid #4080ff;
				border-radius: 16px;
				padding: 0 16px;
				margin: 0;
				transition: all 0.3s ease;

				&:active {
					background: rgba(64, 128, 255, 0.2);
					transform: scale(0.98);
				}

				.btn-text {
					display: inline-block;
					vertical-align: middle;
				}

				&::after {
					border: none;
				}
			}
		}
	}

	.loading,
	.no-more {
		text-align: center;
		padding: 16px;
		color: #999;
		font-size: 14px;
	}

	.footer {
		padding: 16px;
		border-top: 1px solid #f5f5f5;
		background: rgba(255, 255, 255, 0.98);
		backdrop-filter: blur(10px);

		.create-btn {
			background: linear-gradient(135deg, #4080ff 0%, #3366ff 100%);
			color: #fff;
			height: 44px;
			line-height: 44px;
			font-size: 16px;
			font-weight: 500;
			border-radius: 22px;
			border: none;
			box-shadow: 0 4px 12px rgba(64, 128, 255, 0.2);
			transition: all 0.3s ease;

			.btn-text {
				display: inline-block;
				vertical-align: middle;
			}

			&:active {
				transform: translateY(1px);
				box-shadow: 0 2px 8px rgba(64, 128, 255, 0.15);
			}

			&::after {
				border: none;
			}
		}
	}
</style>